  397	    /**
  398	     * Every manager acts on every login (architecture step 3). The engine's selection above is the login's
  399	     * first errand; the managers below then do what a player does in the same login: send every raid the
  400	     * reports and the slots allow, probe a batch of targets, ferry, keep the expedition slot busy, colonise
  401	     * and pick up debris. Arbitration is fixed priority over the shared fleet slots, and the ships each order
  402	     * takes are claimed so the next order plans from what is left. An idle login (DoNothing) is the humaniser's
  403	     * moment and stays idle. How much each manager does is the archetype's doctrine (`managers.yaml`).
  404	     */
  405	    private function runManagers(AiProfile $profile, AiWorkItem $sessionWorkItem, DecisionTrace $trace, AiCandidateActionType $type, CarbonImmutable $afterEconomy): void
  406	    {
  407	        if ($type === AiCandidateActionType::DoNothing) {
  408	            return;
  409	        }
  410	
  411	        $doctrine = app(ManagerDoctrine::class);
  412	        $archetype = $profile->archetype;
  413	        // The account's phase once per login: the numbers below are the archetype's, scaled by how far the
  414	        // account has come (architecture step 4).
  415	        $phase = app(GamePhaseMachine::class)->of(app(PlayerServiceFactory::class)->make($profile->player_id));
  416	        $slots = app(FleetSlots::class)->free($profile->player_id) - $doctrine->int($archetype, 'keep_slots_free', $phase);
  417	
  418	        // Military: raid waves on every report the planner approves, the selected one already placed.
  419	        $waves = $doctrine->int($archetype, 'raid_waves', $phase) - ($type === AiCandidateActionType::Raid ? 1 : 0);
  420	        $selectedReport = (int) ($trace->selected->candidate->parameters['report_id'] ?? 0);
  421	        foreach ($trace->candidates as $scored) {
  422	            if ($waves <= 0 || $slots <= 0) {
  423	                break;
  424	            }
  425	            $candidate = $scored->candidate;
  426	            $reportId = (int) ($candidate->parameters['report_id'] ?? 0);
  427	            if ($candidate->type !== AiCandidateActionType::Raid || $reportId === 0 || $reportId === $selectedReport) {
  428	                continue;
  429	            }
  430	            if ($this->placeRaid($profile, $sessionWorkItem, $reportId, ':raid:' . $reportId)) {
  431	                $waves--;
  432	                $slots--;
  433	            }
  434	        }
  435	
  436	        // Missiles take no fleet slot.
  437	        if ($doctrine->bool($archetype, 'missiles') && $type !== AiCandidateActionType::Missile) {
  438	            $this->asManager(':missile', fn () => $this->scheduleMissile($profile, $sessionWorkItem));
  439	        }
  440	
  441	        // Intel: a batch of probes, each to a different target (the spy planner skips targets already promised).
  442	        $probes = $doctrine->int($archetype, 'probes_per_login', $phase) - ($type === AiCandidateActionType::Spy ? 1 : 0);
  443	        $probed = 0;
  444	        for ($i = 0; $i < $probes && $slots > 0; $i++) {
  445	            if (!$this->asManager(':spy:' . $i, fn () => $this->scheduleSpy($profile, $sessionWorkItem))) {
  446	                break;
  447	            }
  448	            $slots--;
  449	            $probed++;
  450	        }
  451	
  452	        // The rest of the login, one order each while slots remain.
  453	        $errands = [
  454	            'transfer' => [AiCandidateActionType::Transfer, fn () => $this->scheduleTransfer($profile, $sessionWorkItem, $afterEconomy)],
  455	            'expedition' => [AiCandidateActionType::Expedition, fn () => $this->scheduleExpedition($profile, $sessionWorkItem)],
  456	            'colony' => [AiCandidateActionType::Colonize, fn () => $this->scheduleColony($profile, $sessionWorkItem)],
