17	/**
18	 * Module-owned adapter over the normal OGameX research queue.
19	 *
20	 * It exists beside the building adapter for the same reason that one does: the decision is the
21	 * module's, the queue, its requirements and its prices are the host's, and research differs from
22	 * building in one way that matters -- the laboratory that carries it, and the queue that accepts it,
23	 * belong to a planet while the technology belongs to the account.
24	 */
25	class QueueAiResearchAction implements QueueAiResearch
26	{
27	    public function __construct(
28	        private PlayerGameStateService $playerGameStateService,
29	        private PlanetServiceFactory $planetServiceFactory,
30	        private ResearchQueueService $researchQueueService,
31	    ) {
32	    }
33	
34	    public function handle(int $playerId, int $planetId, int $researchId): AiActionResult
35	    {
36	        if (!Planet::query()->whereKey($planetId)->where('user_id', $playerId)->exists()) {
37	            return AiActionResult::rejected(AiQueueActionReason::PlanetNotOwned);
38	        }
39	
40	        try {
41	            $player = $this->playerGameStateService->advance($playerId, $planetId);
42	
43	            if ($player->isBanned()) {
44	                return AiActionResult::rejected(AiQueueActionReason::PlayerBanned);
45	            }
46	            if ($player->isInVacationMode()) {
47	                return AiActionResult::rejected(AiQueueActionReason::VacationMode);
48	            }
49	
50	            $planet = $this->planetServiceFactory->makeForPlayer($player, $planetId, false);
51	            $technology = ObjectService::getObjectById($researchId);
52	            if ($technology->type !== GameObjectType::Research) {
53	                return AiActionResult::rejected(AiQueueActionReason::NotAResearch);
54	            }
55	
56	            // Research is one technology at a time for the whole account, and the host derives the
57	            // target level from the count of rows already active for that technology. Two sessions
58	            // queueing the same technology therefore both aim at the same level, and the host cancels
59	            // the loser as "requirements not met" the moment the first one lands -- which is how 205
60	            // of the newest 300 rows on the grand cohort ended up cancelled. A player does not queue a
61	            // technology that is already in research, so neither does this.
62	            if ($this->researchQueueService->activeResearchQueueItemCount($player, $researchId) > 0) {
63	                return AiActionResult::rejected(AiQueueActionReason::AlreadyResearching);
64	            }
65	
66	            $this->researchQueueService->add($player, $planet, $researchId);
67	            $queueId = ResearchQueue::query()
68	                ->where('planet_id', $planetId)
69	                ->where('object_id', $researchId)
70	                ->latest('id')
71	                ->value('id');
72	
73	            return $queueId === null ? AiActionResult::rejected(AiQueueActionReason::QueueNotCreated) : AiActionResult::queued($queueId);
74	        } catch (Exception $exception) {
75	            return AiActionResult::rejected($exception->getMessage());
76	        }
77	    }
78	}

