398	/** Schedule the selected action and return the intent work item it created. */
399	function intentSchedule(AiProfile $profile, AiCandidateActionType $type, int $planetId, array $parameters = []): ?AiWorkItem
400	{
401	    $session = intentSession($profile, $type->value . '-' . uniqid());
402	    app(ScheduleAiIntentAction::class)->handle($profile, $session, intentTrace($profile->player_id, $planetId, $type, $parameters));
403	
404	    return AiWorkItem::query()->where('idempotency_key', 'intent:session:' . $session->id)->first();
405	}
