414	function intentTrace(int $playerId, int $planetId, AiCandidateActionType $type, array $parameters = [], array $offered = []): DecisionTrace
415	{
416	    $scored = static fn (AiCandidateActionType $candidateType, array $candidateParameters): ScoredCandidate => app()->makeWith(ScoredCandidate::class, [
417	        'candidate' => app()->makeWith(CandidateAction::class, [
418	            'type' => $candidateType,
419	            'reason' => 'intent-fixture',
420	            'parameters' => $candidateParameters,
421	            'features' => ['resource_need' => 0.0, 'safety' => 0.0, 'target_confidence' => 0.0, 'travel_cost' => 0.0, 'recovery' => 0.0],
422	            'sourceTimestamps' => [],
423	        ]),
424	        'score' => 1.0,
425	        'components' => [],
426	    ]);
427	    $selected = $scored($type, $parameters);
428	
429	    return app()->makeWith(DecisionTrace::class, [
430	        'perception' => app()->makeWith(PerceptionSnapshot::class, [
431	            'playerId' => $playerId,
432	            'observedAt' => CarbonImmutable::instance(now()),
433	            'planets' => [],
434	            'targetReports' => [],
435	            'availableActions' => [],
436	            'fleetsaveEligible' => false,
437	            'recoveryFactor' => 0.0,
438	            'sourceTimestamps' => [],
439	            'inboundFleets' => [],
440	        ]),
441	        'candidates' => [$selected, ...array_map(static fn (AiCandidateActionType $other): ScoredCandidate => $scored($other, []), $offered)],
442	        'selected' => $selected,
443	        'rejections' => [],
444	        'inputHash' => 'intent-fixture',
445	    ]);
