 59	    /** @return array<int, CandidateAction> */
 60	    private function publishedCapabilityCandidates(PerceptionSnapshot $perception): array
 61	    {
 62	        $resourceNeed = $perception->totalResources() > self::RESOURCE_RESERVE ? 1.0 : 0.2;
 63	        $candidates = [];
 64	
 65	        foreach (AiCapability::cases() as $capability) {
 66	            // A replay scenario bypasses the perception builder, so a capability the scenario
 67	            // predates is absent rather than false; absent means unpublished, same as the builder.
 68	            if (!($perception->availableActions[$capability->value] ?? false)) {
 69	                continue;
 70	            }
 71	
 72	            $type = $capability->actionType();
 73	            $need = $type === AiCandidateActionType::Build
 74	                ? $resourceNeed + $this->buildScarcityBoost($perception, $resourceNeed)
 75	                : $resourceNeed;
 76	
 77	            // SP8: a spy or colony dispatch the host would refuse for slot exhaustion is
 78	            // never offered — the account checks the fleet screen before sending.
 79	            if (($type === AiCandidateActionType::Spy || $type === AiCandidateActionType::Colonize) && $perception->fleetSlotsFree < 1) {
 80	                continue;
 81	            }
 82	
 83	            // CL3: a colony the account cannot develop outranks nothing, so colonise is
 84	            // offered only when the existing production can bring the new body online.
 85	            if ($type === AiCandidateActionType::Colonize && !$perception->colonizeEligible) {
 86	                continue;
 87	            }
 88	
 89	            $candidates[] = app()->makeWith(CandidateAction::class, [
 90	                'type' => $type,
 91	                'reason' => AiCandidateReason::publishedCapability($capability),
 92	                'parameters' => [],
 93	                'features' => $this->features($type, $need, 0, 0, $perception->recoveryFactor),
 94	                'sourceTimestamps' => $perception->sourceTimestamps,
 95	            ]);
 96	        }
 97	
 98	        return $candidates;
 99	    }
