 69	    public function add(PlanetService $planet, int $building_id): void
 70	    {
 71	        $build_queue = $this->retrieveQueue($planet);
 72	
 73	        // Max amount of buildings that can be in the queue in a given time.
 74	        // TODO: refactor throw exception into a more user-friendly message.
 75	        if ($build_queue->isQueueFull()) {
 76	            // Max amount of build queue items already exist, throw exception.
 77	            throw new Exception('Maximum number of items already in queue.');
 78	        }
 79	
 80	        // Check if user satisfies requirements to build this object.
 81	        $building = ObjectService::getObjectById($building_id);
 82	
 83	        // Only buildings and stations can be added to the building queue.
 84	        if ($building->type !== GameObjectType::Building && $building->type !== GameObjectType::Station) {
 85	            throw new Exception('Only buildings and stations can be added to the building queue.');
 86	        }
 87	
 88	        // Check if building can be built on this planet type (planet or moon).
 89	        $correct_planet_type = ObjectService::objectValidPlanetType($building->machine_name, $planet);
 90	        if (!$correct_planet_type) {
 91	            throw new Exception('This building can not be built on this planet type (planet or moon specific).');
 92	        }
 93	
 94	        // @TODO: add checks that current logged in user is owner of planet
 95	        // and is able to add this object to the building queue.
 96	        $current_level = $planet->getObjectLevel($building->machine_name);
 97	
 98	        // Calculate the level after all queue items (upgrades and downgrades) complete
 99	        // This is the level that the building will be at when this new upgrade starts
100	        $level_after_queue = $current_level;
101	        $queue_items = $this->retrieveQueueItems($planet);
102	        foreach ($queue_items as $item) {
103	            $item_object = ObjectService::getObjectById($item->object_id);
104	            if ($item_object->machine_name === $building->machine_name) {
105	                // Each item sets the level to its target (simulating queue execution)
106	                $level_after_queue = $item->object_level_target;
107	            }
108	        }
109	
110	        // Next upgrade level should be level_after_queue + 1
111	        $next_level = $level_after_queue + 1;
112	
113	        // Check if user satisfies requirements to build this object.
114	        // TODO: refactor throw exception into a more user-friendly message.
115	        $requirements_met = ObjectService::objectRequirementsMetWithQueue($building->machine_name, $next_level, $planet);
116	        if (!$requirements_met) {
117	            throw new Exception('Requirements not met to build this object.');
118	        }
119	
120	        // Check if planet has enough fields for this building (only for buildings that consume fields)
121	        // Ships, defense units, and certain other objects don't consume planet fields
122	        if ($building->consumesPlanetField) {
123	            $currentBuildingCount = $planet->getBuildingCount();
124	            $maxFields = $planet->getPlanetFieldMax();
125	
126	            // The new building would add 1 to the building count
127	            if ($currentBuildingCount >= $maxFields) {
128	                if ($planet->isMoon()) {
129	                    throw new Exception('Not enough fields on this moon. Upgrade your Moon Base or use a moon field item to get more fields.');
130	                } else {
131	                    throw new Exception('Not enough fields on this planet. Upgrade your Terraformer or use a planet field item to get more fields.');
132	                }
133	            }
134	        }
135	
136	        $queue = new BuildingQueue();
137	        $queue->planet_id = $planet->getPlanetId();
138	        $queue->object_id = $building->id;
139	        $queue->object_level_target = $next_level;
140	        $queue->is_downgrade = false; // Explicitly set to false for upgrades
141	
142	        // Save the new queue item
143	        $queue->save();
144	
145	        // Set the new queue item to start (if applicable)
146	        $this->start($planet);
