159	        if ($player === null) {
160	            throw new Exception('Planet has no owner.');
161	        }
162	
163	        $build_queue = $this->retrieveQueue($planet);
164	
165	        // Max amount of buildings that can be in the queue in a given time.
166	        if ($build_queue->isQueueFull()) {
167	            throw new Exception('Maximum number of items already in queue.');
168	        }
169	
170	        // Get the building object
171	        $building = ObjectService::getObjectById($building_id);
172	
173	        // Only buildings and stations can be downgraded
174	        if ($building->type !== GameObjectType::Building &&
175	            $building->type !== GameObjectType::Station) {
176	            throw new Exception('This object cannot be downgraded.');
177	        }
