193	            if ($item_object->machine_name === $building->machine_name) {
194	                // Simulate queue execution: each item updates the level to its target
195	                // For upgrades: level increases to target
196	                // For downgrades: level decreases to target
197	                $level_after_queue = $item->object_level_target;
198	            }
199	        }
