463	     * Cancels an active building queue record.
464	     *
465	     * @param PlanetService $planet
466	     * @param int $building_queue_id
467	     * @param int $building_id
468	     *
469	     * @throws Exception
470	     */
471	    public function cancel(PlanetService $planet, int $building_queue_id, int $building_id): void
472	    {
473	        $queue_item = BuildingQueue::where([
474	            ['id', $building_queue_id],
475	            ['planet_id', $planet->getPlanetId()],
476	            ['object_id', $building_id],
477	            ['processed', 0],
478	            ['canceled', 0],
479	        ])->first();
480	
481	        // If object is found: add canceled flag.
482	        if ($queue_item) {
483	            // Give back resources if the current entry was already building.
484	            if ($queue_item->building === 1) {
485	                $planet->addResources(new Resources($queue_item->metal, $queue_item->crystal, $queue_item->deuterium, 0));
486	            }
487	
488	            // Add canceled flag to the main entry.
489	            $queue_item->building = 0;
490	            $queue_item->canceled = 1;
491	
492	            $queue_item->save();
493	
494	            // Check if requirements for all other items in the queue are still met.
495	            // So e.g. if user cancels build order for metal mine
496	            // level 5 then any other already queued build orders for lvl 6,7,8 etc.
497	            // will also be canceled. Same applies to building requirements,
498	            // if user cancels build order for robotics factory which is requirement
499	            // for shipyard then shipyard will also be canceled.
500	            // Requirements are checked only for building queue objects as
501	            // unit queue objects cannot be canceled.
502	            $this->cancelItemMissingRequirements($planet);
503	
504	            $player = $planet->getPlayer();
505	            if ($player === null) {
506	                throw new Exception('Planet has no owner.');
507	            }
508	
509	            $research_queue = resolve(ResearchQueueService::class);
510	            $research_queue->cancelItemMissingRequirements($player, $planet);
511	
512	            // Set the next queue item to start (if applicable)
513	            $this->start($planet);
514	        }
515	    }
