14	 * Why each planet of an account is or is not building, read from the planner's own candidate
15	 * lists and the host gates it asks. DEV TOOLING, read-only; required by cohort-scenario.php and
16	 * verify-cohorts.php, so a failed economy situation names its cause in the same run.
17	 *
18	 * @return list<string> one line per planet
19	 */
20	function explain_economy(int $playerId): array
21	{
22	    $profile = AiProfile::query()->where('player_id', $playerId)->first();
23	    if ($profile === null) {
24	        return ["player {$playerId} has no AI profile"];
25	    }
26	
27	    $planner = app(QueueableBuildingPlanner::class);
28	    $player = app(PlayerServiceFactory::class)->make($playerId, true);
29	    $taken = [];
30	    foreach ($planner->steps($playerId, $player) as $step) {
31	        $taken[$step->planetId] = $step;
32	    }
33	
34	    $lines = [];
35	    foreach ($player->planets->all() as $planet) {
36	        $id = $planet->getPlanetId();
37	        $resources = $planet->getResources();
38	        $stock = sprintf('metal %s crystal %s deut %s', number_format($resources->metal->get()),
39	            number_format($resources->crystal->get()), number_format($resources->deuterium->get()));
40	
41	        if (DB::table('building_queues')->where('planet_id', $id)->where('processed', 0)->where('canceled', 0)->exists()) {
42	            $lines[] = "p{$id} building | {$stock}";
43	
44	            continue;
45	        }
46	
47	        if (isset($taken[$id])) {
48	            $objectId = $taken[$id] instanceof QueueableResearch ? $taken[$id]->researchId : $taken[$id]->buildingId;
49	            $lines[] = "p{$id} idle, would queue ".ObjectService::getObjectById($objectId)->machine_name." ({$taken[$id]->reason}) | {$stock}";
50	
51	            continue;
52	        }
53	
54	        $why = [];
55	        foreach ($planner->passes($profile) as $pass => $candidates) {
56	            $reasons = [];
57	            foreach ($candidates($planet) as $candidate) {
58	                $reason = ObjectService::getObjectById($candidate->buildingId)->type === GameObjectType::Research
59	                    ? 'technology (lab already taken or refused)'
60	                    : ($planner->refusal($planet, $candidate) ?? 'queueable');
61	                $reasons[$reason] = ($reasons[$reason] ?? 0) + 1;
62	            }
63	            $why[] = $pass.': '.($reasons === [] ? 'no candidate' : implode(', ', array_map(
64	                static fn (string $reason, int $count): string => "{$reason} x{$count}",
65	                array_keys($reasons),
66	                $reasons,
67	            )));
68	        }
69	
70	        $lines[] = "p{$id} IDLE — ".implode('; ', $why)." | {$stock}";
71	    }
72	
73	    return $lines;
74	}

