  231	    /**
  232	     * When the first planet that is short of its next economy step can pay for it.
  233	     *
  234	     * A player who cannot afford the upgrade they want yet does not wait for their next ordinary
  235	     * login: they come back when the resources have arrived, which at universe speed is a few
  236	     * minutes. Without it a login that could not pay for anything left every planet's build queue
  237	     * empty until the routine gap -- the account reads as an idle economy whether or not it is
  238	     * saving (ECON-001: `savingFor()` is the planner's own answer, so no affordability rule and no
  239	     * object is restated here).
  240	     */
  241	    private function affordabilityEta(AiProfile $profile, PerceptionSnapshot $perception, int $nowTimestamp): ?int
  242	    {
  243	        $player = app(PlayerServiceFactory::class)->make($profile->player_id, true);
  244	        $earliest = null;
  245	
  246	        foreach ($perception->planets as $observed) {
  247	            $planet = $this->ownedPlanet($player, (int) ($observed['id'] ?? 0));
  248	            if ($planet === null) {
  249	                continue;
  250	            }
  251	
  252	            // The planner reads live production to price its step, and the session's observation
  253	            // carries only balances: a stale income would put the arrival at the wrong instant.
  254	            $planet->updateResources(false);
  255	            $planet->updateResourceProductionStats(false);
  256	
