    /**
     * The instant this planet's next step becomes payable, or null when it is not waiting on one:
     * it can already pay, or its own mines never bring the resources (no income in a resource the
     * step needs).
     *
     * Affordability is the planner's own word -- the price plus the floor `savingFor()` names -- so
     * a caller that waits for the answer waits for exactly the purchase the queue would take.
     */
    public function savingEta(PlanetService $planet, AiProfile $profile, CarbonImmutable $now): ?CarbonImmutable
    {
        $needed = $this->savingFor($planet, $profile);
        if ($needed === null) {
            return null;
        }

        $held = $planet->getResources();
        $hours = 0.0;

        foreach ([
            [$needed->metal->get(), $held->metal->get(), $planet->getMetalProductionPerHour()],
            [$needed->crystal->get(), $held->crystal->get(), $planet->getCrystalProductionPerHour()],
            [$needed->deuterium->get(), $held->deuterium->get(), $planet->getDeuteriumProductionPerHour()],
        ] as [$cost, $stored, $perHour]) {
            if ($cost <= $stored) {
                continue;
            }
            if ($perHour <= 0.0) {
                return null;
            }
            $hours = max($hours, ($cost - $stored) / $perHour);
        }

        return $hours <= 0.0 ? null : $now->addSeconds((int) ceil($hours * 3600.0));
    }
```

